package com.cowave.search.client.legacy_api

import com.cowave.shared.utils.logger
import kotlinx.coroutines.reactor.awaitSingle
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.http.HttpMethod
import org.springframework.http.MediaType
import org.springframework.stereotype.Component
import org.springframework.web.reactive.function.client.WebClient
import org.springframework.web.reactive.function.client.bodyToMono

@Component
class LegacyApiClient(
    @param:Qualifier("LegacyWebClient")
    private val client: WebClient,
) {
    private val logger by logger()

    suspend fun pushQueue(
        service: String,
        method: HttpMethod,
        body: Any,
    ) {
        try {
            client
                .method(method)
                .uri("/pushQueue.json?service={service}", service)
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue(body)
                .retrieve()
                .bodyToMono<String>()
                .awaitSingle()
        } catch (ex: Exception) {
            logger.error { "Legacy API pushQueue 호출 실패 [service=$service]: $ex" }
            throw ex
        }
    }
}

package com.cowave.search.application.index.service

import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.Catalog
import com.cowave.search.application.index.repository.CatalogIndexRepository
import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.policy.CatalogEvaluator
import com.cowave.search.domain.index.policy.CatalogFilter
import com.cowave.search.domain.index.policy.CatalogMergeStrategy
import com.cowave.shared.domain.dto.IndexResult
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.stereotype.Service

@Service
class CatalogIndexApplicationService(
    private val catalogIndexRepository: CatalogIndexRepository,
    private val catalogAssembleService: CatalogAssembleService,
) {
    fun indexCatalogs(changedData: List<ChangedData<Catalog>>): IndexResult {
        val indexDocuments =
            changedData
                .filter(CatalogFilter::filter)
                .let(CatalogMergeStrategy::merge)
                .let { catalogAssembleService.assemble(it) }
                .filter(CatalogEvaluator::evaluate)

        return catalogIndexRepository.bulk(indexDocuments)
    }
}

